TNL\UI\Conversation::render($thread,true);echo '</div>';?><?php else:?><section class="panel mail-surface" data-live-region="internal-list"><?php if($messages):?><div class="mail-list-heading"><span><?=$folder==='sent'?'Destinatario':'Remitente'?></span><span>Asunto</span><span>Fecha</span></div><div class="mail-list"><?php foreach($messages as $m):?><div class="mail-row-wrap"><input type="checkbox" class="mail-select" aria-label="Seleccionar mensaje"><button type="button" class="mail-actions-toggle button-ghost" aria-label="Acciones del mensaje" aria-expanded="false" data-mail-actions>⋯</button><a class="mail-row <?=($m['unread_count']??($m['read_at']===null?1:0))>0&&$folder==='inbox'?'unread':''?>" href="?folder=<?=tnl_escape($folder)?>&amp;id=<?=(int)$m['id']?>"><span class="mail-sender" title="<?=tnl_escape($m['peer_address'])?>"><?=tnl_escape($m['peer_name'])?></span><span class="mail-subject"><?=tnl_escape($m['subject'])?><?=($m['unread_count']??($m['read_at']===null?1:0))>0&&$folder==='inbox'?' · '.(int)($m['unread_count']??1).' nuevos':''?></span><time class="mail-date"><?=tnl_escape($m['created_at'])?></time></a><form method="post" class="mail-row-actions"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="message_id" value="<?=(int)$m['id']?>"><a class="button button-ghost" href="print.php?kind=internal&amp;id=<?=(int)$m['id']?>" target="_blank" rel="noopener">Imprimir / PDF</a><button class="button-ghost" name="action" value="<?=$folder==='archive'?'unarchive':'archive'?>"><?=$folder==='archive'?'Restaurar':'Archivar'?></button><button class="button-ghost" name="action" value="delete">Borrar</button></form></div><?php endforeach;?></div><?php else:?><div class="empty-state"><span class="card-icon"><?=\TNL\UI\Workspace::icon('mail')?></span><h2>No hay mensajes en esta carpeta</h2><p>Escribe a alguien de tu equipo para comenzar una conversación.</p></div><?php endif;?></section><?php endif;?>
